package br.com.onda;
import android.content.Context;
import android.net.Uri;
import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.util.*;
/** Private playlist cache, replaced only after successful parsing. No background refresh. */
final class IptvStore {
 static File file(Context c){return new File(c.getFilesDir(),"iptv-list.m3u");}
 static List<IptvPlaylist.Channel> read(Context c)throws IOException{File f=file(c);if(!f.exists())return Collections.emptyList();try(InputStream in=new FileInputStream(f)){return IptvPlaylist.read(in,c.getSharedPreferences("iptv",0).getString("base",""));}}
 static List<IptvPlaylist.Channel> save(Context c,InputStream in,String base)throws IOException{BufferedInputStream source=new BufferedInputStream(in);source.mark(8192);ByteArrayOutputStream probe=new ByteArrayOutputStream();for(int i=0;i<4096;i++){int next=source.read();if(next<0)break;probe.write(next);if(next==10&&!probe.toString("UTF-8").replace("\uFEFF","").trim().isEmpty())break;}String prefix=probe.toString("UTF-8").replace("\uFEFF","").trim();source.reset();if(!prefix.startsWith("#EXTM3U")&&!prefix.startsWith("#EXTINF:"))throw new IOException("O arquivo não contém um cabeçalho M3U válido.");File temp=File.createTempFile("iptv-import-",".m3u",c.getCacheDir());try{try(OutputStream out=new FileOutputStream(temp)){byte[] b=new byte[65536];int n;while((n=source.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();out.write(b,0,n);}}List<IptvPlaylist.Channel> result;try(InputStream data=new FileInputStream(temp)){result=IptvPlaylist.read(data,base);}if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();Files.move(temp.toPath(),file(c).toPath(),StandardCopyOption.REPLACE_EXISTING);c.getSharedPreferences("iptv",0).edit().putString("base",base==null?"":base).apply();return result;}finally{temp.delete();}}
 static List<IptvPlaylist.Channel> download(Context c,String raw)throws IOException{return download(c,raw,connection->{});}
 static List<IptvPlaylist.Channel> download(Context c,String raw,java.util.function.Consumer<HttpURLConnection> observer)throws IOException{String source=IptvPlaylist.stream(raw,"");if(source.isEmpty()||!source.startsWith("https://"))throw new IOException("Use um link HTTPS ou importe o arquivo M3U. Canais HTTP também podem ser reproduzidos a partir do arquivo.");String url=source;for(int redirects=0;redirects<6;redirects++){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setConnectTimeout(15000);connection.setReadTimeout(15000);connection.setInstanceFollowRedirects(false);connection.setRequestProperty("Accept","application/vnd.apple.mpegurl, audio/x-mpegurl, text/plain, */*");observer.accept(connection);try{int status=connection.getResponseCode();if(status>=300&&status<400){String next=connection.getHeaderField("Location");if(next==null)throw new IOException("Redirecionamento inválido.");url=IptvPlaylist.stream(next,url);if(!url.startsWith("https://"))throw new IOException("O servidor redirecionou para um endereço sem HTTPS. Importe o arquivo M3U.");continue;}if(status!=200)throw new IOException("O servidor da lista respondeu HTTP "+status+".");try(InputStream in=connection.getInputStream()){return save(c,in,url);}}finally{connection.disconnect();observer.accept(null);}}throw new IOException("Muitos redirecionamentos na lista.");}
}
